"                     <div className="p-6 bg-[#161b22] border-t border-[#30363d] flex gap-3 justify-end shrink-0">
                        <button onClick={() => setIsAccessLevelModalOpen(false)} className="px-6 py-2.5 bg-[#21262d] text-[#c9d1d9] rounded-xl text-[10px] font-black uppercase hover:bg-[#30363d]">Cancel</button>
                        <button onClick={() => {
                           const defaultAccess = {
                              todaysSale: true,
                              totalSale: true,
                              itemPieChart: true,
                              barSalesChart: true,
                              thisMonthSale: true,
                              lineSalesChart: true,
                              allSalesAnalysis: true,
                              paymentModesChart: true,
                              salesAnalysisByDays: true,
                              ipAddress: true
                           };
                           setAccessLevels(defaultAccess);
                           localStorage.setItem('pos_access_levels', JSON.stringify(defaultAccess));
                           toast.success("Settings Reset!");
                        }} className="px-6 py-2.5 bg-red-600/20 text-red-500 rounded-xl text-[10px] font-black uppercase hover:bg-red-600/30">Reset</button>
                        <button onClick={() => {
                           localStorage.setItem('pos_access_levels', JSON.stringify(accessLevels));
                           toast.success("Access Levels Updated!");
                           setIsAccessLevelModalOpen(false);
                        }} className="px-6 py-2.5 bg-[#10ac84] text-white rounded-xl text-[10px] font-black uppercase hover:bg-[#0e936f]">Update</button>
                     </div>"
